/**
 * Parses one line of a Claude Code transcript (~/.claude/projects/<proj>/<session>.jsonl).
 *
 * NOTE: The transcript format is not a documented public API and may change between
 * Claude Code versions. Keep all format knowledge in this file.
 */

export type AccessKind = 'read' | 'edit';

export type TranscriptEvent =
  | { kind: 'meta'; sessionId: string; cwd?: string; timestamp?: number }
  /**
   * `ai`: generated by Claude Code. `custom`: the user renamed the session (an empty title means the
   * name was cleared). Claude Code keeps writing `ai-title` lines after a rename, so `custom` wins.
   */
  | { kind: 'title'; sessionId: string; title: string; source: 'ai' | 'custom' }
  | {
      kind: 'file';
      sessionId: string;
      cwd?: string;
      timestamp: number;
      tool: string;
      access: AccessKind;
      filePath: string;
    }
  /** Any tool call (used to know which tool a later result belongs to). */
  | { kind: 'toolUse'; sessionId: string; toolUseId: string; tool: string }
  /** A tool call finished: ran after approval, failed, or was denied. */
  | { kind: 'toolResult'; sessionId: string; toolUseId: string; timestamp: number }
  /** The user sent a message in the main conversation. */
  | { kind: 'prompt'; sessionId: string; timestamp: number }
  /**
   * A skill or custom command was used: the `Skill` tool (Claude invoked it) or a slash command
   * the user typed (`<command-name>/x</command-name>`; built-in commands like /clear appear too).
   */
  | { kind: 'skill'; sessionId: string; name: string; via: 'tool' | 'command'; timestamp: number };

const EDIT_TOOLS: Record<string, string> = {
  Edit: 'file_path',
  MultiEdit: 'file_path',
  Write: 'file_path',
  NotebookEdit: 'notebook_path',
};

const READ_TOOLS: Record<string, string> = {
  Read: 'file_path',
};

export function parseLine(line: string): TranscriptEvent[] {
  let rec: any;
  try {
    rec = JSON.parse(line);
  } catch {
    return [];
  }
  if (!rec || typeof rec !== 'object' || typeof rec.sessionId !== 'string') {
    return [];
  }

  const sessionId: string = rec.sessionId;
  const events: TranscriptEvent[] = [];

  if (rec.type === 'ai-title' && typeof rec.aiTitle === 'string') {
    events.push({ kind: 'title', sessionId, title: rec.aiTitle, source: 'ai' });
    return events;
  }
  if (rec.type === 'custom-title' && typeof rec.customTitle === 'string') {
    events.push({ kind: 'title', sessionId, title: rec.customTitle.trim(), source: 'custom' });
    return events;
  }

  const timestamp = rec.timestamp ? Date.parse(rec.timestamp) : NaN;
  const cwd: string | undefined = typeof rec.cwd === 'string' ? rec.cwd : undefined;

  if (cwd || !Number.isNaN(timestamp)) {
    events.push({
      kind: 'meta',
      sessionId,
      cwd,
      timestamp: Number.isNaN(timestamp) ? undefined : timestamp,
    });
  }

  const ts = Number.isNaN(timestamp) ? Date.now() : timestamp;
  if (rec.type === 'user') {
    events.push(...userEvents(rec, sessionId, ts));
  } else if (rec.type === 'assistant' && Array.isArray(rec.message?.content)) {
    for (const block of rec.message.content) {
      events.push(...toolUseEvents(block, sessionId, cwd, ts));
    }
  }
  return events;
}

/** A `tool_use` block → the call itself, plus a file access for file tools. */
function toolUseEvents(block: any, sessionId: string, cwd: string | undefined, ts: number): TranscriptEvent[] {
  if (block?.type !== 'tool_use' || typeof block.name !== 'string') {
    return [];
  }
  const events: TranscriptEvent[] = [];
  if (typeof block.id === 'string') {
    events.push({ kind: 'toolUse', sessionId, toolUseId: block.id, tool: block.name });
  }
  if (block.name === 'Skill' && typeof block.input?.skill === 'string' && block.input.skill) {
    events.push({ kind: 'skill', sessionId, name: block.input.skill.replace(/^\//, ''), via: 'tool', timestamp: ts });
  }
  const editKey = EDIT_TOOLS[block.name];
  const key = editKey ?? READ_TOOLS[block.name];
  const filePath = key ? block.input?.[key] : undefined;
  if (typeof filePath === 'string' && filePath) {
    events.push({ kind: 'file', sessionId, cwd, timestamp: ts, tool: block.name, access: editKey ? 'edit' : 'read', filePath });
  }
  return events;
}

/**
 * `user` records carry either tool results (one per finished tool call; denials included, with
 * `toolDenialKind`) or a message the user typed. Meta records (injected context) and sidechain
 * (subagent) records are not the user typing.
 */
function userEvents(rec: any, sessionId: string, ts: number): TranscriptEvent[] {
  const content = rec.message?.content;
  if (Array.isArray(content)) {
    const results: TranscriptEvent[] = content
      .filter((b: any) => b?.type === 'tool_result' && typeof b.tool_use_id === 'string')
      .map((b: any) => ({ kind: 'toolResult', sessionId, toolUseId: b.tool_use_id, timestamp: ts }));
    if (results.length > 0) {
      return results;
    }
  }
  const typed = typeof content === 'string' || (Array.isArray(content) && content.some((b: any) => b?.type === 'text'));
  if (!typed || rec.isMeta === true || rec.isSidechain === true) {
    return [];
  }
  const events: TranscriptEvent[] = [{ kind: 'prompt', sessionId, timestamp: ts }];
  const command = SLASH_COMMAND_RE.exec(messageText(content));
  if (command) {
    events.push({ kind: 'skill', sessionId, name: command[1], via: 'command', timestamp: ts });
  }
  return events;
}

const SLASH_COMMAND_RE = /<command-name>\/?([^<\s]+)<\/command-name>/;

function messageText(content: any): string {
  if (typeof content === 'string') {
    return content;
  }
  return content
    .filter((b: any) => b?.type === 'text' && typeof b.text === 'string')
    .map((b: any) => b.text)
    .join('\n');
}
